mapper.select:
SELECT r.RECIPE_ID, r.TITLE, r.SOURCE_TYPE, r.CHANNEL_NAME, r.VIDEO_URL, r.THUMBNAIL_URL, r.COOK_TIME_MIN, r.DIFFICULTY, r.SERVINGS, r.ONE_PAN_YN, r.MICROWAVE_YN, r.SCORE_WEIGHT, r.VIEW_COUNT, r.CREATED_AT, NVL(ROUND(AVG(e.RATING), 1), 0.0) AS AVG_RATING, COUNT(e.EVAL_ID) AS EVAL_COUNT FROM RECIPES r LEFT JOIN RECIPE_EVALUATIONS e ON r.RECIPE_ID = e.RECIPE_ID
AND (r.TITLE LIKE '%' || #{keyword} || '%' OR r.CHANNEL_NAME LIKE '%' || #{keyword} || '%')
AND r.SOURCE_TYPE = #{sourceType}
AND r.DIFFICULTY = #{difficulty}
AND r.ONE_PAN_YN = #{onePanYn}
GROUP BY r.RECIPE_ID, r.TITLE, r.SOURCE_TYPE, r.CHANNEL_NAME, r.VIDEO_URL, r.THUMBNAIL_URL, r.COOK_TIME_MIN, r.DIFFICULTY, r.SERVINGS, r.ONE_PAN_YN, r.MICROWAVE_YN, r.SCORE_WEIGHT, r.VIEW_COUNT, r.CREATED_AT ORDER BY r.SCORE_WEIGHT DESC, r.VIEW_COUNT DESC, r.RECIPE_ID DESC

mapper.insert:
INSERT INTO RECIPE_INGREDIENTS (
    RECIPE_ID, INGREDIENT_NAME, AMOUNT, UNIT, IS_ESSENTIAL, IS_BASIC_SAUCE
) VALUES (
    #{recipeId}, #{ingredientName}, #{amount}, #{unit}, #{isEssential}, #{isBasicSauce}
)

INSERT INTO RECIPE_STEPS (
    RECIPE_ID, STEP_ORDER, INSTRUCTION, TIMER_SECONDS, TIP
) VALUES (
    #{recipeId}, #{stepOrder}, #{instruction}, #{timerSeconds}, #{tip}
)
